// Tópico: mackenzie/bueiro-inteligente/{id_bueiro}/sensor/{campo}
const partes = msg.topic.split('/');
const idBueiro = partes[2];
const campo = partes[4];
const valor = parseFloat(msg.payload);

if (isNaN(valor)) {
    node.warn(`Valor inválido em ${msg.topic}: ${msg.payload}`);
    return null;
}

// Limites de classificação do nível de obstrução (%)
const LIMITE_ATENCAO = 50; // a partir de 50% -> amarelo
const LIMITE_CRITICO = 75; // a partir de 75% -> vermelho

// Guarda a última distância de cada bueiro
const distancias = flow.get('distancias') || {};
if (campo === 'distancia') {
    distancias[idBueiro] = valor;
    flow.set('distancias', distancias);
    return null;
}

// Chegou a obstrução: classifica o nível
let status;
if (valor >= LIMITE_CRITICO) status = 'vermelho';
else if (valor >= LIMITE_ATENCAO) status = 'amarelo';
else status = 'verde';

msg.topic = idBueiro;
msg.id_bueiro = idBueiro;
msg.status = status;
msg.obstrucao_pct = valor;
msg.distancia_cm = (distancias[idBueiro] !== undefined) ? distancias[idBueiro] : null;

const cores = { verde: 'green', amarelo: 'yellow', vermelho: 'red' };
node.status({ fill: cores[status], shape: 'dot', text: `${idBueiro}: ${valor}% (${status})` });

return msg;

// Cadastro fixo da localização de cada bueiro (latitude, longitude e endereço).
// Para adicionar um novo bueiro, basta incluir uma nova linha aqui.
const cadastroBueiros = {
    bueiro01: {
        latitude: -23.5475,
        longitude: -46.6520,
        endereco: 'Rua da Consolação, 930 - Consolação'
    }
};

const local = cadastroBueiros[msg.id_bueiro];

const campos = {
    obstrucao_pct: msg.obstrucao_pct,
    status: msg.status
};

if (msg.distancia_cm !== null) {
    campos.distancia_cm = msg.distancia_cm;
}

if (local) {
    campos.latitude = local.latitude;
    campos.longitude = local.longitude;
    campos.endereco = local.endereco;
} else {
    node.warn(`Bueiro ${msg.id_bueiro} sem localização cadastrada.`);
}

// [campos, tags]
msg.payload = [campos, { id_bueiro: msg.id_bueiro }];
return msg;

const token = env.get('TELEGRAM_BOT_TOKEN');
const chatId = env.get('TELEGRAM_CHAT_ID');

if (!token || !chatId) {
    node.warn('Configure TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID nas variáveis de ambiente da aba.');
    return null;
}

// Cadastro dos bueiros (mesmo da function "Montar ponto InfluxDB")
const cadastroBueiros = {
    bueiro01: { endereco: 'Rua da Consolação, 930 - Consolação, São Paulo/SP' }
};

// Endereço do dashboard no Grafana (substitua pelo da sua instância)
const LINK_DASHBOARD = env.get('LINK_DASHBOARD') || 'https://SEU-STACK.grafana.net';

const local = cadastroBueiros[msg.id_bueiro];
const endereco = local ? local.endereco : 'Endereço não cadastrado';

const obstrucao = Number(msg.obstrucao_pct).toFixed(1);
const distancia = (msg.distancia_cm !== null && msg.distancia_cm !== undefined)
    ? `${Number(msg.distancia_cm).toFixed(1)} cm`
    : 'não disponível';

const dataHora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const texto =
    `🚨 <b>ALERTA CRÍTICO – BUEIRO INTELIGENTE</b>\n` +
    `\n` +
    `<b>Bueiro:</b> ${msg.id_bueiro}\n` +
    `<b>Endereço:</b> ${endereco}\n` +
    `<b>Nível de obstrução:</b> ${obstrucao}%\n` +
    `<b>Distância medida:</b> ${distancia}\n` +
    `<b>Data/hora:</b> ${dataHora}\n` +
    `\n` +
    `⚠️ <b>Ação recomendada:</b> encaminhar equipe de zeladoria para limpeza preventiva, ` +
    `a fim de evitar entupimento e risco de alagamento.\n` +
    `\n` +
    `📊 <a href="${LINK_DASHBOARD}">Acompanhar no dashboard</a>`;

msg.url = `https://api.telegram.org/bot${token}/sendMessage`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    chat_id: chatId,
    text: texto,
    parse_mode: 'HTML',
    disable_web_page_preview: true
};
return msg;

// mackenzie/bueiro-inteligente/{id_bueiro}/{dispositivo}/conexao
const partes = msg.topic.split('/');
msg.payload = `${partes[2]} / ${partes[3]}: ${msg.payload}`;
return msg;
